# -*- coding: utf-8 -*-
"""Deutschland / Naturwissenschaften Klasse 5–6（Biologie und Physik）"""
from de_sci import H, nq, num, NB


def f_temp(R):
    k = R.choice(["diff", "diff", "steigt", "faellt"])
    if k == "diff":
        a = R.randint(-12, 6)
        b = a + R.randint(4, 18)
        return nq("Morgens zeigt das Thermometer %s °C, nachmittags %s °C. Um wie viel Grad ist es wärmer geworden?" % (num(a), num(b)), b - a,
                  [abs(b + a), b, abs(a)], "°C", "Unterschied: %s − (%s) = %d °C." % (num(b), num(a), b - a))
    if k == "steigt":
        a = R.randint(-10, 10)
        d = R.randint(3, 15)
        return nq("Es sind %s °C. Die Temperatur steigt um %d °C. Wie warm ist es jetzt?" % (num(a), d), a + d, [abs(a - d), d, abs(a) + d + 2], "°C",
                  "%s + %d = %s °C." % (num(a), d, num(a + d))) if a + d > 0 else None
    a = R.randint(8, 25)
    d = R.randint(2, a - 1)
    return nq("Am Abend sind es %d °C. In der Nacht sinkt die Temperatur um %d °C. Wie kalt ist es dann?" % (a, d), a - d, [a + d, d, a - d + 10], "°C", "%d − %d = %d °C." % (a, d, a - d))


def f_schall(R):
    k = R.choice(["gewitter", "gewitter", "echo", "zeit"])
    if k == "gewitter":
        t = R.choice([2, 3, 4, 5, 6, 8, 9, 10, 12, 15])
        return nq("Zwischen Blitz und Donner vergehen %d Sekunden. Wie weit ist das Gewitter ungefähr entfernt? (Schall: 340 m in 1 s)" % t, 340 * t,
                  [340 / t, 340 * t / 2, 340 + t, 300 * t], "m", "Entfernung = 340 m/s · %d s = %s m. Faustregel: Sekunden durch 3 ergibt etwa die Kilometer." % (t, num(340 * t)))
    if k == "echo":
        t = R.choice([1, 2, 3, 4, 6])
        return nq("Du rufst gegen eine Felswand. Das Echo kommt nach %d Sekunden zurück. Wie weit ist die Wand entfernt? (Schall: 340 m in 1 s)" % t, 340 * t / 2,
                  [340 * t, 340 / t, 170 / t], "m", "Der Schall läuft hin und zurück: 340 · %d = %s m, die Hälfte ist %s m." % (t, num(340 * t), num(340 * t / 2)))
    s = R.choice([680, 1020, 1360, 1700, 2040, 3400])
    return nq("Ein Gewitter ist %s m entfernt. Nach wie vielen Sekunden hörst du den Donner? (Schall: 340 m in 1 s)" % num(s), s / 340,
              [s / 34, s * 340, s / 170], "s", "Zeit = %s m : 340 m/s = %s s." % (num(s), num(s / 340)))


